on conflict (name, country) do update set
  -- Numele, regiunea și coordonatele rândului existent rămân: au
  -- fost verificate de mână și sunt referite de anunțuri publicate.
  -- Restul se completează, fiindcă lipsea.
  population = coalesce(excluded.population, localities.population),
  is_county_seat = localities.is_county_seat or excluded.is_county_seat,
  aliases = (select array(select distinct e from unnest(localities.aliases || excluded.aliases) e where e <> ''));

